71	@RestController
72	@CrossOrigin(exposedHeaders = "errors, content-type")
73	@RequestMapping("/api")
74	public class OwnerRestControllerV1 implements OwnersApi {
75	
76	    /**
77	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that
78	     * contains at least one dot, with no whitespace anywhere. Deliberately lenient — it accepts
79	     * ordinary addresses while rejecting clearly malformed ones such as {@code not-an-email}.
80	     */
81	    private static final Pattern EMAIL_PATTERN =
82	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
83	
84	    /**
85	     * Disposable email domains that are refused on create. An email whose domain (the part after the
86	     * {@code @}, compared case-insensitively) is in this set is rejected with a 400, since such
87	     * addresses are throwaway and unsuitable for contacting an owner.
88	     */
89	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
90	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
91	
92	    /**
93	     * Dedicated audit logger. On a successful create an audit line carrying the owner id, the
94	     * customerCode, the registrationDate and the membershipLevel is emitted through this logger.
95	     */
96	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
97	
98	    /**
99	     * Remembers the owner created for each {@code Idempotency-Key} seen on a create, so a repeated
100	     * create carrying a key already in this map returns the originally created owner (200) instead of
101	     * creating a duplicate. Keys are supplied by the caller and are process-wide.
102	     */
103	    private final java.util.Map<String, Integer> idempotencyKeys = new java.util.concurrent.ConcurrentHashMap<>();
104	
105	    private final ClinicService clinicService;
106	
107	    private final OwnerMapper ownerMapper;
108	
109	    private final PetMapper petMapper;
110	
111	    private final VisitMapper visitMapper;
112	
113	    public OwnerRestControllerV1(ClinicService clinicService,
114	                                 OwnerMapper ownerMapper,
115	                                 PetMapper petMapper,
116	                                 VisitMapper visitMapper) {
117	        this.clinicService = clinicService;
118	        this.ownerMapper = ownerMapper;
119	        this.petMapper = petMapper;
120	        this.visitMapper = visitMapper;
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
126	        Collection<Owner> owners;
127	        if (lastName != null) {
128	            owners = this.clinicService.findOwnerByLastName(lastName);
129	        } else {
130	            owners = this.clinicService.findAllOwners();
131	        }
132	        if (owners.isEmpty()) {
133	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
134	        }
135	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
136	    }
137	
138	    /**
139	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
140	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
141	     */
142	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
143	        List<String> missing = new ArrayList<>();
144	        if (isBlank(ownerFieldsDto.getFirstName())) {
145	            missing.add("firstName");
146	        }
147	        if (isBlank(ownerFieldsDto.getLastName())) {
148	            missing.add("lastName");
149	        }
150	        if (isBlank(ownerFieldsDto.getAddress())) {
151	            missing.add("address");
152	        }
153	        if (isBlank(ownerFieldsDto.getCity())) {
154	            missing.add("city");
155	        }
156	        if (isBlank(ownerFieldsDto.getTelephone())) {
157	            missing.add("telephone");
158	        }
159	        if (!missing.isEmpty()) {
160	            throw new RequiredFieldsMissingException(missing);
161	        }
162	    }
163	
164	    private static boolean isBlank(String value) {
165	        return value == null || value.isBlank();
166	    }
167	
168	    /**
169	     * Normalizes an address on create: leading/trailing whitespace is trimmed, every run of internal
170	     * whitespace is collapsed to a single space, the value is upper-cased and common abbreviations are
171	     * expanded token-by-token ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The
172	     * normalized value is what gets stored, returned and used for every address comparison; a value
173	     * that is blank (or {@code null}) normalizes to the empty string so the required-field check
174	     * rejects it.
175	     *
176	     * @param address the raw address as supplied by the caller, may be {@code null}
177	     * @return the normalized address ({@code ""} when blank or {@code null})
178	     */
179	    private static String normalizeAddress(String address) {
180	        if (address == null) {
181	            return "";
182	        }
183	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
184	        if (collapsed.isEmpty()) {
185	            return "";
186	        }
187	        String[] tokens = collapsed.split(" ");
188	        StringBuilder sb = new StringBuilder(collapsed.length());
189	        for (int i = 0; i < tokens.length; i++) {
190	            String token = tokens[i];
191	            switch (token) {
192	                case "ST" -> token = "STREET";
193	                case "RD" -> token = "ROAD";
194	                case "AVE" -> token = "AVENUE";
195	                default -> { }
196	            }
197	            if (i > 0) {
198	                sb.append(' ');
199	            }
200	            sb.append(token);
201	        }
202	        return sb.toString();
203	    }
204	
205	    /**
206	     * Resolves and normalizes the owner's address on create, supporting both the structured form
207	     * ({@code addressLine1} / {@code addressLine2}) and the flat {@code address} form kept for
208	     * backward compatibility. Whichever address fields are supplied are normalized (see
209	     * {@link #normalizeAddress(String)}). The structured form is preferred when present: when
210	     * {@code addressLine1} is non-blank the composed {@code address} is the normalized
211	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when
212	     * {@code addressLine2} is present; otherwise the composed {@code address} is the normalized flat
213	     * {@code address}. The normalized structured fields are written back so they are stored and
214	     * returned, and the composed value is written to {@code address} so everything that reads the
215	     * address (the household hash, postcode validation and locality) uses the structured fields when
216	     * present, falling back to the flat address. When neither form supplies an address the composed
217	     * {@code address} is blank, so the required-field check rejects it.
218	     *
219	     * @param ownerFieldsDto the owner payload whose address fields are normalized in place
220	     */
221	    private static void applyAddress(OwnerFieldsDto ownerFieldsDto) {
222	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
223	        String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
224	        String flat = normalizeAddress(ownerFieldsDto.getAddress());
225	        String composed;
226	        if (!line1.isEmpty()) {
227	            composed = line2.isEmpty() ? line1 : line1 + " " + line2;
228	        } else {
229	            composed = flat;
230	        }
231	        ownerFieldsDto.setAddressLine1(line1.isEmpty() ? null : line1);
232	        ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
233	        ownerFieldsDto.setAddress(composed);
234	    }
235	
236	    /**
237	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
238	     * A leading {@code +} and its country code are kept as given; otherwise the country code
239	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
240	     * The result must carry 8 to 15 digits after the {@code +}. In addition, when the country code
241	     * is recognized the national number must have the exact length that code requires ({@code +61}
242	     * expects 9 national digits, {@code +1} expects 10). Returns the E.164 string to be stored and
243	     * returned.
244	     *
245	     * @param telephone the raw telephone as supplied by the caller
246	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
247	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
248	     *     national-number length is wrong for its country code
249	     */
250	    private static String normalizeTelephone(String telephone) {
251	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
252	        String e164;
253	        if (cleaned.startsWith("+")) {
254	            e164 = "+" + cleaned.substring(1);
255	        } else {
256	            String national = cleaned;
257	            if (national.startsWith("0")) {
258	                national = national.substring(1);
259	            }
260	            e164 = "+61" + national;
261	        }
262	        String digits = e164.substring(1);
263	        if (!digits.matches("\\d{8,15}")) {
264	            throw new InvalidTelephoneException(
265	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
266	        }
267	        if (digits.startsWith("61")) {
268	            requireNationalLength(digits.substring(2), 9, "+61");
269	        } else if (digits.startsWith("1")) {
270	            requireNationalLength(digits.substring(1), 10, "+1");
271	        }
272	        return e164;
273	    }
274	
275	    /**
276	     * Enforces that the national portion of an E.164 number has the exact number of digits its
277	     * country code requires.
278	     *
279	     * @param national the national-number digits (the part after the country code)
280	     * @param expected the exact national-number length the country code requires
281	     * @param countryCode the country code, for the error message
282	     * @throws InvalidTelephoneException if {@code national} does not have exactly {@code expected} digits
283	     */
284	    private static void requireNationalLength(String national, int expected, String countryCode) {
285	        if (national.length() != expected) {
286	            throw new InvalidTelephoneException(
287	                "Telephone with country code '" + countryCode + "' must have " + expected
288	                    + " national digits");
289	        }
290	    }
291	
292	    /**
293	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
294	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
295	     *
296	     * @param email the raw email as supplied by the caller, may be {@code null}
297	     * @return the lower-cased email, or {@code null} when none was supplied
298	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
299	     */
300	    private static String normalizeEmail(String email) {
301	        if (email == null || email.isBlank()) {
302	            return null;
303	        }
304	        String trimmed = email.trim();
305	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
306	            throw new InvalidEmailException("Email must be a syntactically valid address");
307	        }
308	        String lowerCased = trimmed.toLowerCase(Locale.ROOT);
309	        String domain = lowerCased.substring(lowerCased.indexOf('@') + 1);
310	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
311	            throw new InvalidEmailException("Email domain is not allowed");
312	        }
313	        return lowerCased;
314	    }
315	
316	    /**
317	     * Derives the single duplicate-detection key that consolidates the former separate telephone,
318	     * email and household checks. The key is {@code normalizedTelephone + '|' + email + '|' +
319	     * householdId}, where the email segment is the empty string when the owner has no email. Because
320	     * the telephone is part of the key, two owners that differ in any one segment (for example two
321	     * members of the same household with different telephones) produce different keys.
322	     *
323	     * @param normalizedTelephone the E.164 telephone of the owner
324	     * @param email the lower-cased email of the owner, may be {@code null}
325	     * @param householdId the stable household identifier of the owner, may be {@code null}
326	     * @return the derived identity key
327	     */
328	    private static String deriveIdentityKey(String normalizedTelephone, String email, String householdId) {
329	        return (normalizedTelephone == null ? "" : normalizedTelephone)
330	            + "|" + (email == null ? "" : email)
331	            + "|" + (householdId == null ? "" : householdId);
332	    }
333	
334	    /**
335	     * Rejects a create only when the new owner's whole {@code identityKey} equals that of an existing
336	     * owner. This one check replaces the former separate telephone, email and household duplicate
337	     * checks: only an exact full-key match is a duplicate, so two owners that differ in any single
338	     * segment are both allowed. Each existing owner's key is derived from its stored, already
339	     * normalized telephone, email and household identifier.
340	     *
341	     * @param identityKey the derived identity key of the owner being created
342	     * @throws DuplicateIdentityException if another owner already has this identity key
343	     */
344	    /**
345	     * The existing owners considered by the create endpoint's duplicate and identity checks:
346	     * every owner that is not soft-deleted. A soft-deleted owner retains its row but is ignored
347	     * here, so a create that would otherwise be blocked by it is allowed.
348	     *
349	     * @return a stream of the owners not flagged deleted
350	     */
351	    private java.util.stream.Stream<Owner> activeOwners() {
352	        return this.clinicService.findAllOwners().stream()
353	            .filter(existing -> !existing.isDeleted());
354	    }
355	
356	    private void rejectDuplicateIdentity(String identityKey) {
357	        boolean inUse = activeOwners()
358	            .anyMatch(existing -> identityKey.equals(
359	                deriveIdentityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
360	        if (inUse) {
361	            throw new DuplicateIdentityException(
362	                "An owner with the same identity key already exists");
363	        }
364	    }
365	
366	    /**
367	     * Rejects a create when an existing owner already belongs to the same household (i.e. carries the
368	     * same computed {@code householdId}, derived from last name and postcode), unless the request
369	     * knowingly opts in via {@code sharesHousehold}. Setting {@code sharesHousehold} bypasses this
370	     * block so the owner is created as a declared member of the existing household; without it, a
371	     * second owner in the same household is a conflict.
372	     *
373	     * @param householdId the computed household identifier of the owner being created
374	     * @param sharesHousehold whether the request opted in to sharing an existing household
375	     * @throws DuplicateHouseholdException if the household already exists and the request did not opt in
376	     */
377	    private void rejectDuplicateHousehold(String householdId, boolean sharesHousehold) {
378	        if (sharesHousehold) {
379	            return;
380	        }
381	        boolean exists = activeOwners()
382	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
383	        if (exists) {
384	            throw new DuplicateHouseholdException(
385	                "An owner with the same last name and postcode already exists");
386	        }
387	    }
388	
389	    /**
390	     * Finds a soft-match "possible duplicate" for the owner being created: an existing owner that is
391	     * not a hard identity duplicate but shares this owner's last name (compared case-insensitively) and
392	     * postcode while carrying a different telephone. When the postcode is absent no owner can share it,
393	     * so there is never a match. When several existing owners qualify the one with the lowest id is
394	     * returned, so the result is deterministic.
395	     *
396	     * @param lastName the last name of the owner being created
397	     * @param postcode the postcode of the owner being created, may be {@code null}
398	     * @param normalizedTelephone the E.164 telephone of the owner being created
399	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
400	     */
401	    private Integer findPossibleDuplicateOf(String lastName, String postcode, String normalizedTelephone) {
402	        if (postcode == null || postcode.isBlank()) {
403	            return null;
404	        }
405	        String normalizedLastName = normalizeName(lastName);
406	        return activeOwners()
407	            .filter(existing -> normalizedLastName.equals(normalizeName(existing.getLastName())))
408	            .filter(existing -> postcode.equals(existing.getPostcode()))
409	            .filter(existing -> !normalizedTelephone.equals(existing.getTelephone()))
410	            .map(Owner::getId)
411	            .filter(java.util.Objects::nonNull)
412	            .min(Integer::compareTo)
413	            .orElse(null);
414	    }
415	
416	    /**
417	     * Derives the stable household identifier for an owner from its last name and postcode. The value
418	     * is the first twelve hex characters of the SHA-256 of {@code normalizedLastName + '|' + postcode}
419	     * (the last name normalized case-insensitively with surrounding whitespace trimmed; an absent
420	     * postcode contributes the empty string). Because it is a pure function of those two fields, every
421	     * owner with the same last name and postcode is assigned the same identifier automatically, without
422	     * any existing record having to be updated.
423	     *
424	     * @param lastName the last name of the owner being created
425	     * @param postcode the postcode of the owner being created, may be {@code null}
426	     * @return the stable household identifier
427	     */
428	    private static String householdId(String lastName, String postcode) {
429	        String key = normalizeName(lastName) + "|" + (postcode == null ? "" : postcode);
430	        return sha256HexPrefix(key, 12);
431	    }
432	
433	    /**
434	     * The maximum number of owners a single city may contain. A create whose city already holds this
435	     * many owners is rejected, so a city never grows beyond this capacity.
436	     */
437	    private static final int CITY_CAPACITY = 50;
438	
439	    /**
440	     * Rejects a create whose city already contains {@link #CITY_CAPACITY} or more owners, so no city
441	     * ever exceeds its capacity. Cities are compared case-insensitively with surrounding whitespace
442	     * trimmed. The count reflects the
443	     * state before the new owner is persisted, so it excludes the owner being created.
444	     *
445	     * @param city the city of the owner being created
446	     * @throws CityAtCapacityException if the city already contains {@link #CITY_CAPACITY} owners
447	     */
448	    private void rejectCityAtCapacity(String city) {
449	        String normalizedCity = normalizeName(city);
450	        long ownersInCity = this.clinicService.findAllOwners().stream()
451	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
452	            .count();
453	        if (ownersInCity >= CITY_CAPACITY) {
454	            throw new CityAtCapacityException(
455	                "The city already contains the maximum number of owners");
456	        }
457	    }
458	
459	    /**
460	     * The maximum number of owners that may be created on a single day. A create made once this many
461	     * owners already carry today's {@code registrationDate} is rejected, so no more than this many
462	     * owners are registered per day.
463	     */
464	    private static final int DAILY_OWNER_LIMIT = 100;
465	
466	    /**
467	     * Rejects a create once {@link #DAILY_OWNER_LIMIT} or more owners have already been created for
468	     * the given business day, counted by {@code registrationDate} equal to the effective (weekend
469	     * rolled forward) registration date of the owner being created. The count reflects the state
470	     * before the new owner is persisted, so it excludes the owner being created.
471	     *
472	     * @param registrationDate the effective business-day registration date of the owner being created
473	     * @throws DailyOwnerLimitExceededException if the day already holds {@link #DAILY_OWNER_LIMIT} owners
474	     */
475	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
476	        long ownersToday = this.clinicService.findAllOwners().stream()
477	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
478	            .count();
479	        if (ownersToday >= DAILY_OWNER_LIMIT) {
480	            throw new DailyOwnerLimitExceededException(
481	                "The maximum number of owners for today has already been reached");
482	        }
483	    }
484	
485	    /**
486	     * The number of owners that may already exist for a business day before a create is flagged with
487	     * a bulk-signup warning. Once more than this many owners already carry the effective registration
488	     * date, the created owner's {@code bulkSignupWarning} is set to {@code true}.
489	     */
490	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
491	
492	    /**
493	     * Determines whether a create should be flagged with a bulk-signup warning, i.e. whether more than
494	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for the given business day,
495	     * counted by {@code registrationDate} equal to the effective (weekend rolled forward) registration
496	     * date of the owner being created. The count reflects the state before the new owner is persisted,
497	     * so it excludes the owner being created.
498	     *
499	     * @param registrationDate the effective business-day registration date of the owner being created
500	     * @return {@code true} when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the date
501	     */
502	    private boolean bulkSignupWarning(LocalDate registrationDate) {
503	        long ownersToday = this.clinicService.findAllOwners().stream()
504	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
505	            .count();
506	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
507	    }
508	
509	    /** Fixed public holidays the business-day roll skips. */
510	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
511	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
512	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
513	        LocalDate.parse("2026-12-28"));
514	
515	    /**
516	     * Rolls a registration date forward to a business day: any date landing on a Saturday, Sunday or
517	     * listed public holiday is advanced one day at a time until it reaches the next non-holiday
518	     * weekday, and any other weekday is returned unchanged.
519	     *
520	     * @param date the effective registration date, supplied or defaulted to the server date
521	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
522	     */
523	    private static LocalDate toBusinessDay(LocalDate date) {
524	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
525	                || date.getDayOfWeek() == DayOfWeek.SUNDAY
526	                || PUBLIC_HOLIDAYS.contains(date)) {
527	            date = date.plusDays(1);
528	        }
529	        return date;
530	    }
531	
532	    /**
533	     * Builds the customer code assigned to an owner on create, formatted {@code '<REGION>-<HASH8>'}
534	     * where {@code REGION} is the region code derived from the owner's postcode (the region whose
535	     * inclusive range contains the postcode, or {@code 'UNKNOWN'} when the postcode is absent or in
536	     * no known range) and {@code HASH8} is the first eight upper-cased hex characters of the SHA-256
537	     * of {@code normalizedTelephone + lastName}, e.g. {@code 'NSW-1A2B3C4D'}. There is no sequence
538	     * component: the identity is a pure region-and-hash value.
539	     *
540	     * @param postcode the postcode of the owner being created, may be {@code null}
541	     * @param normalizedTelephone the E.164 telephone of the owner being created
542	     * @param lastName the last name of the owner being created
543	     * @return the formatted customer code
544	     */
545	    private String customerCode(String postcode, String normalizedTelephone, String lastName) {
546	        return regionFromPostcode(postcode) + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
547	    }
548	
549	    /**
550	     * De-duplicates a freshly computed customer code against the customer codes already held by
551	     * existing owners. When the code is unused it is returned unchanged; otherwise {@code '-<n>'} is
552	     * appended with the smallest {@code n} of 2 or more that yields a code no existing owner carries.
553	     *
554	     * @param customerCode the computed customer code for the owner being created
555	     * @return the same code when unique, otherwise the code with a {@code '-<n>'} suffix that makes
556	     *     it unique
557	     */
558	    private String deduplicateCustomerCode(String customerCode) {
559	        Set<String> existing = new java.util.HashSet<>();
560	        for (Owner owner : this.clinicService.findAllOwners()) {
561	            if (owner.getCustomerCode() != null) {
562	                existing.add(owner.getCustomerCode());
563	            }
564	        }
565	        if (!existing.contains(customerCode)) {
566	            return customerCode;
567	        }
568	        int n = 2;
569	        while (existing.contains(customerCode + "-" + n)) {
570	            n++;
571	        }
572	        return customerCode + "-" + n;
573	    }
574	
575	    /**
576	     * Returns the region code whose inclusive postcode range contains the given 4-digit postcode
577	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code 'UNKNOWN'} when the postcode is
578	     * {@code null}, non-numeric, or in no known range.
579	     *
580	     * @param postcode the postcode, may be {@code null}
581	     * @return the region code, or {@code 'UNKNOWN'}
582	     */
583	    private static String regionFromPostcode(String postcode) {
584	        if (postcode == null || postcode.isBlank()) {
585	            return "UNKNOWN";
586	        }
587	        int code;
588	        try {
589	            code = Integer.parseInt(postcode.trim());
590	        } catch (NumberFormatException e) {
591	            return "UNKNOWN";
592	        }
593	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
594	            int[] range = entry.getValue();
595	            if (code >= range[0] && code <= range[1]) {
596	                return entry.getKey();
597	            }
598	        }
599	        return "UNKNOWN";
600	    }
601	
602	    /**
603	     * Computes the SHA-256 of {@code value} and returns its first {@code length} hex characters,
604	     * upper-cased.
605	     *
606	     * @param value the string to hash
607	     * @param length the number of leading hex characters to return
608	     * @return the upper-cased hex prefix of the digest
609	     */
610	    private static String sha256HexPrefix(String value, int length) {
611	        try {
612	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
613	            StringBuilder sb = new StringBuilder(digest.length * 2);
614	            for (byte b : digest) {
615	                sb.append(String.format("%02x", b));
616	            }
617	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
618	        } catch (NoSuchAlgorithmException e) {
619	            throw new IllegalStateException("SHA-256 not available", e);
620	        }
621	    }
622	
623	    /**
624	     * Counts the existing owners that share the owner-to-be's first and last name, compared
625	     * case-insensitively (surrounding whitespace trimmed). The count reflects the state before the
626	     * new owner is persisted, so it excludes the owner being created.
627	     *
628	     * @param firstName the first name of the owner being created
629	     * @param lastName the last name of the owner being created
630	     * @return the number of existing owners with the same first and last name
631	     */
632	    private int countNamesakes(String firstName, String lastName) {
633	        String normalizedFirstName = normalizeName(firstName);
634	        String normalizedLastName = normalizeName(lastName);
635	        return (int) this.clinicService.findAllOwners().stream()
636	            .filter(existing ->
637	                normalizedFirstName.equals(normalizeName(existing.getFirstName()))
638	                    && normalizedLastName.equals(normalizeName(existing.getLastName())))
639	            .count();
640	    }
641	
642	    /**
643	     * Counts the members of the owner-to-be's household after this create, i.e. one more than the
644	     * number of existing owners already carrying the same {@code householdId}. The household
645	     * identifier is a deterministic function of last name and postcode, so a solo owner (the only one
646	     * with that identifier) is a household of one. The count includes the owner being created (hence
647	     * the {@code + 1}).
648	     *
649	     * @param householdId the stable household identifier of the owner being created
650	     * @return the number of household members after this create (always at least 1)
651	     */
652	    private int householdSize(String householdId) {
653	        if (householdId == null) {
654	            return 1;
655	        }
656	        return (int) this.clinicService.findAllOwners().stream()
657	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
658	            .count() + 1;
659	    }
660	
661	    /**
662	     * Normalizes a name for case-insensitive comparison by trimming surrounding whitespace and
663	     * lower-casing.
664	     *
665	     * @param value the raw name, may be {@code null}
666	     * @return the normalized name ({@code ""} when {@code value} is {@code null})
667	     */
668	    private static String normalizeName(String value) {
669	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
670	    }
671	
672	    /**
673	     * The fixed city-to-region table used to validate a postcode against its city
674	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). A city not in this table has no known region and
675	     * therefore accepts any 4-digit postcode.
676	     */
677	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
678	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
679	
680	    /**
681	     * The fixed region-to-postcode-range table: each region admits an inclusive 4-digit range
682	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
683	     */
684	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
685	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
686	
687	    /**
688	     * Validates an owner's optional postcode on create. A {@code null} or blank postcode is left
689	     * untouched (postcode is optional when absent). When present it must be exactly four digits and,
690	     * when the city maps to a known region, must fall within that region's inclusive range
691	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
692	     * postcode.
693	     *
694	     * @param city the city of the owner being created
695	     * @param postcode the raw postcode as supplied by the caller, may be {@code null}
696	     * @throws InvalidPostcodeException if a present postcode is not four digits or is out of range
697	     *     for the city's region
698	     */
699	    private static void validatePostcode(String city, String postcode) {
700	        if (postcode == null || postcode.isBlank()) {
701	            return;
702	        }
703	        if (!postcode.matches("\\d{4}")) {
704	            throw new InvalidPostcodeException("Postcode must be exactly 4 digits");
705	        }
706	        String region = CITY_REGION.get(city);
707	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
708	        if (range != null) {
709	            int value = Integer.parseInt(postcode);
710	            if (value < range[0] || value > range[1]) {
711	                throw new InvalidPostcodeException(
712	                    "Postcode is out of range for the city's region");
713	            }
714	        }
715	    }
716	
717	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
718	    @Override
719	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
720	        Owner owner = this.clinicService.findOwnerById(ownerId);
721	        if (owner == null) {
722	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
723	        }
724	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
725	    }
726	
727	    /**
728	     * Reads the caller-supplied {@code Idempotency-Key} header from the current request, if any. The
729	     * header is absent for ordinary creates; when present and non-blank it enables the idempotent-create
730	     * behaviour keyed on its value.
731	     *
732	     * @return the trimmed idempotency key, or {@code null} when the header is absent or blank
733	     */
734	    private static String currentIdempotencyKey() {
735	        var attributes = org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
736	        if (!(attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttributes)) {
737	            return null;
738	        }
739	        String key = servletAttributes.getRequest().getHeader("Idempotency-Key");
740	        return (key == null || key.isBlank()) ? null : key.trim();
741	    }
742	
743	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
744	    @Override
745	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
746	        String idempotencyKey = currentIdempotencyKey();
747	        if (idempotencyKey != null) {
748	            Integer existingId = idempotencyKeys.get(idempotencyKey);
749	            if (existingId != null) {
750	                Owner existing = this.clinicService.findOwnerById(existingId);
751	                if (existing != null) {
752	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
753	                }
754	            }
755	        }
756	        applyAddress(ownerFieldsDto);
757	        validateRequiredFields(ownerFieldsDto);
758	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
759	        if (registrationDate == null) {
760	            registrationDate = LocalDate.now();
761	        } else if (registrationDate.isAfter(LocalDate.now())) {
762	            throw new FutureRegistrationDateException(
763	                "registrationDate must not be later than the server date");
764	        }
765	        registrationDate = toBusinessDay(registrationDate);
766	        ownerFieldsDto.setRegistrationDate(registrationDate);
767	        rejectDailyOwnerLimit(registrationDate);
768	        rejectCityAtCapacity(ownerFieldsDto.getCity());
769	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
770	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
771	        ownerFieldsDto.setTelephone(normalizedTelephone);
772	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
773	        ownerFieldsDto.setEmail(normalizedEmail);
774	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
775	        String ownerHouseholdId = householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
776	        rejectDuplicateIdentity(deriveIdentityKey(normalizedTelephone, normalizedEmail, ownerHouseholdId));
777	        rejectDuplicateHousehold(ownerHouseholdId, sharesHousehold);
778	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicateOf(
779	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode(), normalizedTelephone);
780	        HttpHeaders headers = new HttpHeaders();
781	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
782	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
783	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
784	        owner.setCustomerCode(deduplicateCustomerCode(customerCode(
785	            ownerFieldsDto.getPostcode(), normalizedTelephone, ownerFieldsDto.getLastName())));
786	        owner.setHouseholdId(ownerHouseholdId);
787	        owner.setHouseholdSize(householdSize(ownerHouseholdId));
788	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
789	        owner.setBulkSignupWarning(bulkSignupWarning(registrationDate));
790	        this.clinicService.saveOwner(owner);
791	        if (idempotencyKey != null) {
792	            idempotencyKeys.put(idempotencyKey, owner.getId());
793	        }
794	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
795	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
796	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
797	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
798	        headers.setLocation(UriComponentsBuilder.newInstance()
799	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
800	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
801	    }
